contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with parameters driving C.transfer
    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        // require non-empty _tos to match C.transfer's require and reach core behavior
        require(_tos.length > 0);

        bool reverted;
        bool ret;
        // call transfer and catch revert
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }

        // General rule: when precondition _tos.length>0 holds, transfer must not revert and must return true
        assert(!reverted && ret == true);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(_tos.length > 0);

        bool reverted;
        bool returnedFalse;

        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            returnedFalse = (r == false);
        } catch {
            reverted = true;
            returnedFalse = false;
        }

        // General rule: when precondition holds, it cannot both not revert and return false
        assert(!(reverted == false && returnedFalse == true));
    }

    receive() external payable {}
}

